evals.setup_script:
STATE="${TMPDIR:-/tmp}/herdr-eval-state"; mkdir -p "$STATE"
CWD="$HOME/.herdr-eval-repo"   # the repository fixture_script created
# Stacking splits leaves the fourth pane about a dozen columns wide, too narrow for an agent to start.
# Split across tabs instead so each gets the full width.
for n in alpha bravo charlie delta; do
  OUT=$(herdr tab create --workspace "$HERDR_WORKSPACE_ID" --cwd "$CWD" --no-focus) || {
    echo "failed to create a tab — aborting"; exit 1; }
  set -- $(printf '%s' "$OUT" | python3 -c 'import sys, json
r = json.load(sys.stdin)["result"]
print(r["tab"]["tab_id"], r["root_pane"]["pane_id"])')
  [ -n "$1" ] && [ -n "$2" ] || { echo "could not read the tab response — aborting"; exit 1; }
  echo "$1" >> "$STATE/tabs"
  herdr agent start "$n" --kind claude --pane "$2" >/dev/null || {
    echo "failed to start $n — aborting"; exit 1; }
done
herdr agent list   # confirm all four are idle
